import { nanoid } from "nanoid";

import { db } from "../db.js";
import { projects } from "../schema.js";

// G2 (defect): creates the project of a client request; the request id
// makes the INSERT idempotent. A resubmitted request (the client got no
// response) or a duplicate submission generates a new id, its INSERT does
// nothing, and the response carries an id that no row has: the stored row's
// id was generated by the earlier attempt.
export async function createProject(requestId: string, ownerId: number) {
  const id = nanoid();
  await db
    .insert(projects)
    .values({ id, requestId, ownerId })
    .onConflictDoNothing({ target: projects.requestId });
  return { id };
}

// G2-safe: the same INSERT as an upsert that returns the stored row's id:
// the id generated by whichever attempt created the row.
export async function createProjectSafe(requestId: string, ownerId: number) {
  const id = nanoid();
  const [row] = await db
    .insert(projects)
    .values({ id, requestId, ownerId })
    .onConflictDoUpdate({ target: projects.requestId, set: { requestId } })
    .returning({ id: projects.id });
  return { id: row?.id ?? null };
}
